// PHÂN TÍCH SLA CHÍNH XÁC THEO SCHEMA SUPABASE THỰC TẾ
const now = new Date();
const results = [];

for (const item of $input.all()) {
  const data = item.json;

  // 1. Kiểm tra: Chưa nộp video (videoLink rỗng hoặc null)
  const hasVideo = data.videoLink && typeof data.videoLink === 'string' && data.videoLink.trim().length > 5;
  if (hasVideo) continue;

  // 2. Bỏ qua các đơn đã hoàn thành hoặc bị từ chối
  if (data.status === 'Đã hoàn thành' || data.status === 'Bị từ chối' || data.status === 'Từ chối') {
    continue;
  }

  // 3. Tính ngày chính xác từ created_at (ISO) hoặc createdAtDate (DD/MM/YYYY)
  let eventDate = null;
  if (data.created_at) {
    eventDate = new Date(data.created_at);
  } else if (data.createdAtDate && typeof data.createdAtDate === 'string' && data.createdAtDate.includes('/')) {
    const parts = data.createdAtDate.split('/');
    if (parts.length === 3) {
      eventDate = new Date(parseInt(parts[2]), parseInt(parts[1]) - 1, parseInt(parts[0]));
    }
  }

  if (!eventDate || isNaN(eventDate.getTime())) continue;

  const diffMs = now.getTime() - eventDate.getTime();
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

  // Làm sạch handle TikTok
  const rawHandle = data.tiktokHandle || 'koc';
  const cleanHandle = rawHandle.startsWith('@') ? rawHandle.slice(1) : rawHandle;
  const kocName = data.kocName || 'KOC';
  const campaignName = data.campaignName || 'Chiến dịch KOCity';
  const shippingCode = data.shippingCode || 'Chưa có';
  const phone = data.phone || 'Chưa cập nhật';
  const shippingStatus = data.shippingStatus || 'Đang vận chuyển';

  let alertType = 'normal';
  let alertTitle = '';
  let alertMessage = '';

  // Điều kiện phân loại SLA 5-7 ngày
  if (diffDays >= 7) {
    alertType = 'OVERDUE';
    alertTitle = '🚨 [QUÁ HẠN NỘP VIDEO >7 NGÀY]';
    alertMessage = `KOC <b>${kocName}</b> đã nhận hàng được <b>${diffDays} ngày</b> nhưng CHƯA nộp link video! Cần liên hệ giục gấp.`;
  } else if (diffDays >= 5) {
    alertType = 'WARNING_48H';
    alertTitle = '⏳ [CẬN HẠN 48H - CẦN GIỤC VIDEO]';
    alertMessage = `KOC <b>${kocName}</b> đã nhận hàng được <b>${diffDays} ngày</b>, chỉ còn 1-2 ngày là hết hạn nộp video.`;
  } else if (diffDays >= 1 && diffDays < 2) {
    alertType = 'UNBOXING_REMINDER';
    alertTitle = '🎁 [NHẮC QUAY UNBOXING NGÀY 1]';
    alertMessage = `KOC <b>${kocName}</b> vừa nhận hàng mẫu ngày đầu tiên. Nhắc KOC quay clip unboxing ngay!`;
  }

  if (alertType !== 'normal') {
    results.push({
      json: {
        id: data.id,
        kocName,
        cleanHandle,
        campaignName,
        phone,
        shippingCode,
        shippingStatus,
        diffDays,
        alertType,
        alertTitle,
        alertMessage
      }
    });
  }
}

return results;

